import re

def extract(text):
    result = {
        "kar_payi_orani": [],
        "finansman_orani": [],
        "finansman_tutari": [],
        "vade": [],
        "taksit_sayisi": [],
        "masraf_bilgisi": [],
        "hedef_kitle": [],
        "para_birimi": [],
        "kosullar": []
    }

    # finansman_tutari: min/max amounts
    tutar_pattern = r"minimum\s+(\d+(?:\.\d+)?)\s*(?:TL|TRY|USD|EUR)|(\d+(?:\.\d+)?)\s*(?:TL|TRY|USD|EUR)\s*,\s*maksimum\s+(\d+(?:\.\d+)?)\s*(?:TL|TRY|USD|EUR)"
    tutar_matches = re.findall(tutar_pattern, text, re.IGNORECASE)
    if tutar_matches:
        for match in tutar_matches:
            amounts = [m for m in match if m]
            if len(amounts) == 2:
                result["finansman_tutari"].append(f"minimum {amounts[0]} TL, maksimum {amounts[1]} TL")
            elif len(amounts) == 1:
                result["finansman_tutari"].append(f"minimum {amounts[0]} TL")
    else:
        # fallback: look for standalone amounts with TL
        amount_matches = re.findall(r"(\d{1,3}(?:\.\d{3})*(?:,\d+)?)\s*TL", text)
        if amount_matches:
            # Filter to only those near financing context
            for m in re.finditer(r"(\d{1,3}(?:\.\d{3})*(?:,\d+)?)\s*TL", text):
                span = m.span()
                context = text[max(0, span[0]-50):min(len(text), span[1]+50)]
                if "finansman" in context.lower() or "tutar" in context.lower():
                    result["finansman_tutari"].append(f"{m.group(1)} TL")

    # vade: min/max months
    vade_pattern = r"minimum\s+(\d+)\s*(?:ay|ay\s*,\s*maksimum\s+(\d+)\s*ay)"
    vade_matches = re.findall(vade_pattern, text, re.IGNORECASE)
    if vade_matches:
        for match in vade_matches:
            if match[0] and match[1]:
                result["vade"].append(f"minimum {match[0]} ay, maksimum {match[1]} ay")
            elif match[0]:
                result["vade"].append(f"minimum {match[0]} ay")
    else:
        vade_matches = re.findall(r"(\d+)\s*(?:ay|ay\s*,\s*maksimum\s+(\d+)\s*ay)", text, re.IGNORECASE)
        if vade_matches:
            for match in vade_matches:
                if match[0] and match[1]:
                    result["vade"].append(f"minimum {match[0]} ay, maksimum {match[1]} ay")
                elif match[0]:
                    result["vade"].append(f"minimum {match[0]} ay")

    # para_birimi: explicit currency mentions
    para_birimi_matches = re.findall(r"\b(TL|TRY|USD|EUR)\b", text, re.IGNORECASE)
    if para_birimi_matches:
        result["para_birimi"] = list(set(para_birimi_matches))

    # kosullar: conditions not captured elsewhere
    kosullar_snippets = []
    # Extract the "Dikkat Edilmesi Gereken Hususlar" section
    dikkat_match = re.search(r"Dikkat Edilmesi Gereken Hususlar\s*([\s\S]*?)(?:\n\n|\Z)", text)
    if dikkat_match:
        section = dikkat_match.group(1)
        # Extract sentences about conditions
        sentences = re.split(r"[.!?]+", section)
        for s in sentences:
            s = s.strip()
            if any(keyword in s.lower() for keyword in ["vade", "finansman", "tutar", "abonelik", "tesisat", "kullanılacaktır"]):
                if s:
                    kosullar_snippets.append(s.strip())
    if kosullar_snippets:
        result["kosullar"] = kosullar_snippets

    # hedef_kitle: target audience
    hedef_kitle_match = re.search(r"(?:Enerya|Doğalgaz dönüşüm|yeni abonelik) (?:için|konusunda|kapsamında)?\s*(?:aboneler|müşteriler|kullanıcılar|kullanıcılar|hedeflenen|uygun olan)\b", text, re.IGNORECASE)
    if hedef_kitle_match:
        result["hedef_kitle"].append(hedef_kitle_match.group(0).strip())
    else:
        # Look for geographic targeting
        il_match = re.search(r"(?:Antalya|Aydın|Denizli|Konya)\s*illerinde", text)
        if il_match:
            result["hedef_kitle"].append(f"{il_match.group(0)} için")

    # masraf_bilgisi: fees/expenses
    masraf_match = re.search(r"(?:masraf|ücret|komisyon|yönetim|dağıtım)\s*(?:bedeli|miktarı|tutarı|bilgisi|bilgisi|bilgisi)", text, re.IGNORECASE)
    if masraf_match:
        # Extract surrounding context
        start = max(0, masraf_match.start() - 20)
        end = min(len(text), masraf_match.end() + 50)
        result["masraf_bilgisi"].append(text[start:end].strip())

    # finansman_orani: financing ratio
    orani_match = re.search(r"finansman\s*(?:orani|oranı|orani|oranı)\s*[:\s]+(\d+(?:,\d+)?\s*%)", text, re.IGNORECASE)
    if orani_match:
        result["finansman_orani"].append(orani_match.group(1).replace(",", "."))

    # kar_payi_orani: profit/share rate
    kar_match = re.search(r"(?:kar|pay|payı)\s*(?:orani|oranı|orani|oranı)\s*[:\s]+(\d+(?:,\d+)?\s*%)", text, re.IGNORECASE)
    if kar_match:
        result["kar_payi_orani"].append(kar_match.group(1).replace(",", "."))

    # taksit_sayisi: installment count
    taksit_match = re.search(r"(\d+)\s*(?:taksit|taksitli|ödeme planı)", text, re.IGNORECASE)
    if taksit_match:
        result["taksit_sayisi"].append(taksit_match.group(1))

    # Clean up empty lists
    for key in result:
        if not result[key]:
            result[key] = []

    return result

