        r'Türkiye\s*Finans\s*Katılım\s*Bankası\s*AŞ\s*bu\s*kampanyayı\s*uzatma,\s*durdurma,\s*kampanya\s*şartlarını\s*değiştirme\s*ve/veya\s*kampanyayı\s*tek\s*taraflı\s*olarak\s*sonlandırma\s*hakkını\s*saklı\s*tutar'
    ]
    for pattern in kosullar_patterns:
        matches = re.findall(pattern, text, re.IGNORECASE)
        for m in matches:
            if m not in result["kosullar"]:
                result["kosullar"].append(m.strip())

    # Additional cleanup: remove duplicates and empty strings
    for key in result:
        result[key] = list(dict.fromkeys([s for s in result[key] if s]))

    return result

import re

def extract(text):
    result = {
        "kar_payi_orani": [],
        "finansman_orani": [],
        "finansman_tutari": [],
        "vade": [],
        "taksit_sayisi": [],
        "masraf_bilgisi": [],
        "hedef_kitle": [],
        "para_birimi": [],
        "kosullar": []
    }

    # kar_payi_orani: look for explicit "kâr payı oranı" or "kâr oranları"
    kar_payi_matches = re.findall(r'[Kk]âr\s*[Pp]ay[iı]?\s*[Oo]ran[iı]?\s*[=:]\s*([0-9.,%]+)', text)
    if not kar_payi_matches:
        kar_payi_matches = re.findall(r'[Kk]âr\s*[Oo]ran[iı]?\s*[=:]\s*([0-9.,%]+)', text)
    if not kar_payi_matches:
        # look for percentages in the table under "Kâr Payı Oranı"
        kar_payi_matches = re.findall(r'Kâr\s*[Pp]ay[iı]?\s*[Oo]ran[iı]?\s*[\n\r]+([0-9.,%]+)', text)
    if not kar_payi_matches:
        # fallback: find standalone percentages in the table section
        table_section = re.search(r'İhtiyaç Finansmanın maksimum vadesi.*', text, re.DOTALL)
        if table_section:
            kar_payi_matches = re.findall(r'([0-9]+(?:\.[0-9]+)?(?:,[0-9]+)?%?)\s*%', table_section.group(0))
    # Normalize and clean
    for m in kar_payi_matches:
        val = m.strip()
        if val and val not in result["kar_payi_orani"]:
            result["kar_payi_orani"].append(val)

    # finansman_orani: look for financing ratio (finansman oranı)
    finansman_orani_matches = re.findall(r'[Ff]inansman\s*[Oo]ran[iı]?\s*[=:]\s*([0-9.,%]+)', text)
    for m in finansman_orani_matches:
        val = m.strip()
        if val and val not in result["finansman_orani"]:
            result["finansman_orani"].append(val)

    # finansman_tutari: look for explicit financing amounts
    # Look for "Finansman Tutarı" column and values
    finansman_tutari_matches = re.findall(r'Finansman\s*[Tt]utar[iı]?\s*[\n\r]+([0-9.,]+)\s*TL', text)
    if not finansman_tutari_matches:
        # Try to find standalone amounts in the table
        finansman_tutari_matches = re.findall(r'([0-9]{3,}(?:[.,][0-9]+)?)\s*TL', text)
    for m in finansman_tutari_matches:
        val = m.strip()
        if val and val not in result["finansman_tutari"]:
            result["finansman_tutari"].append(val)

    # vade: look for maturity/term info
    vade_matches = re.findall(r'[Vv]ade\s*[=:]\s*([0-9]+\s*(?:ay|yıl))', text)
    if not vade_matches:
        vade_matches = re.findall(r'([0-9]+)\s*(?:ay|yıl)', text)
        # Filter to likely vade values (e.g., 6, 9, 12, 18, 24, 36)
        vade_matches = [v for v in vade_matches if v in ['6', '9', '10', '12', '18', '24', '36']]
    # Also capture "36 aya varan" phrase
    vade_varan = re.findall(r'([0-9]+)\s*aya\s*varan', text)
    for m in vade_matches + vade_varan:
        val = m.strip()
        if val and val not in result["vade"]:
            result["vade"].append(val + " ay")

    # taksit_sayisi: installment count
    taksit_sayisi_matches = re.findall(r'[Tt]aksit\s*[Ss]ay[iı]?\s*[=:]\s*([0-9]+)', text)
    if not taksit_sayisi_matches:
        # Look for number of installments in table: "6", "9", etc. under "Taksit Sayısı" or similar
        taksit_sayisi_matches = re.findall(r'[\n\r]([0-9]+)\s*[\n\r]+[0-9.,]+\s*TL\s*[\n\r]+[0-9.,%]+\s*%', text)
        # Extract just the first number
        taksit_sayisi_matches = re.findall(r'[\n\r]([0-9]+)\s*[\n\r]+[0-9.,]+\s*TL', text)
    for m in taksit_sayisi_matches:
        val = m.strip()
        if val and val not in result["taksit_sayisi"]:
            result["taksit_sayisi"].append(val)

    # masraf_bilgisi: fees, expenses
    masraf_matches = re.findall(r'[Mm]asraf|ücret|komisyon|yönetim\s*[Ff]ee|dosya\s*[Ff]ee', text, re.IGNORECASE)
    if masraf_matches:
        # Extract sentences containing fee-related terms
        sentences = re.split(r'[.!?]+', text)
        for s in sentences:
            if re.search(r'[Mm]asraf|[Kk]omisyon|[Yy]önetim\s*[Ff]ee|[Dd]osya\s*[Ff]ee', s, re.IGNORECASE):
                result["masraf_bilgisi"].append(s.strip())
    # Also check for "banka finansman başvurularını serbestçe değerlendirme..." sentence
    fee_sentence = re.search(r'Banka\s+finansman\s+başvurularını\s+serbestçe\s+değerlendirme.*?hakkına\s+sahiptir\.', text, re.IGNORECASE)
    if fee_sentence:
        result["masraf_bilgisi"].append(fee_sentence.group(0).strip())

    # hedef_kitle: target audience
    hedef_kitle_matches = re.findall(r'[Bb]ireysel\s+[Kk]ullan[iı]mc[iı]|\s[Bb]ireysel\s+[Mm]üşter[iı]|\s[Bb]ireysel\s+[Kk]at[iı]l[iı]mc[iı]', text)
    if hedef_kitle_matches:
        result["hedef_kitle"].append("Bireysel kullanıcı/müşteri")
    # Also check for explicit "hedef kitle" or "uygun olanlar"
    hedef_kitle_matches2 = re.findall(r'[Hh]edef\s+[Kk]itle\s*[=:]\s*([^\n]+)', text)
    for m in hedef_kitle_matches2:
        if m.strip():
            result["hedef_kitle"].append(m.strip())

    # para_birimi: currency
    para_birimi_matches = re.findall(r'(TL|TRY|USD|EUR)', text)
    for m in para_birimi_matches:
        val = m.strip()
        if val and val not in result["para_birimi"]:
            result["para_birimi"].append(val)

    # kosullar: conditions not captured elsewhere
    # Look for eligibility, application, usage conditions
    kosullar_matches = re.findall(r'[Bb]aşvuru\s+[Ff]ormlar[iı]|\s[Gg]erekli\s+[Bb]elgeler|\s[Kk]oşullar|\s[Ee]l[iı]gibilirlik', text, re.IGNORECASE)
    if kosullar_matches:
        # Extract relevant sentences
        sentences = re.split(r'[.!?]+', text)
        for s in sentences:
            if re.search(r'[Bb]aşvuru\s+[Ff]ormlar[iı]|\s[Gg]erekli\s+[Bb]elgeler|\s[Kk]oşullar|\s[Ee]l[iı]gibilirlik', s, re.IGNORECASE):
                result["kosullar"].append(s.strip())
    # Also capture the sentence about bank's rights
    bank_rights = re.search(r'Banka\s+finansman\s+başvurularını\s+serbestçe\s+değerlendirme.*?hakkına\s+sahiptir\.', text, re.IGNORECASE)
    if bank_rights:
        result["kosullar"].append(bank_rights.group(0).strip())

    # Ensure all lists are unique and non-empty
    for key in result:
        result[key] = list(dict.fromkeys(result[key]))  # remove duplicates while preserving order

    return result

import re

def extract(text):
    result = {
        "kar_payi_orani": [],
        "finansman_orani": [],
        "finansman_tutari": [],
        "vade": [],
        "taksit_sayisi": [],
        "masraf_bilgisi": [],
        "hedef_kitle": [],
        "para_birimi": [],
        "kosullar": []
    }

    # kar_payi_orani
    kar_patterns = [
        r'%(\d+(?:,\d+)?)\s*kâr',
        r'%(\d+(?:,\d+)?)\s*Kar',
        r'Aylık\s*Kâr\s*Oranı\s*%(\d+(?:,\d+)?)',
        r'Yıllık\s*Maliyet\s*Oranı',
        r'Efektif\s*Yıllık\s*Kar\s*Oranı'
    ]
    for pattern in kar_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            result["kar_payi_orani"].append(match.group(0).strip())

    # finansman_orani
    finansman_orani_match = re.search(r'arazinin\s+%(\d+)\s*’üne\s*kadar\s*finansman', text, re.IGNORECASE)
    if finansman_orani_match:
        result["finansman_orani"].append("%" + finansman_orani_match.group(1))
    else:
        finansman_orani_match = re.search(r'%(\d+)\s*peşin\s*alım\s*indirimi', text, re.IGNORECASE)
        if finansman_orani_match:
            result["finansman_orani"].append("%" + finansman_orani_match.group(1))

    # finansman_tutari
    finansman_tutari_match = re.search(r'Finansman\s*Tutarı', text)
    if finansman_tutari_match:
        # Look for amount patterns nearby
        amount_match = re.search(r'(\d+(?:\.\d{3})*(?:,\d{2})?)\s*TL', text)
        if amount_match:
            result["finansman_tutari"].append(amount_match.group(0))
        else:
            result["finansman_tutari"].append("Belirtilmemiş")

    # vade
    vade_match = re.search(r'(\d+)\s*aya\s*varan\s*vade', text, re.IGNORECASE)
    if vade_match:
        result["vade"].append(vade_match.group(0))
    else:
        vade_match = re.search(r'(\d+)\s*aylık\s*vade', text, re.IGNORECASE)
        if vade_match:
            result["vade"].append(vade_match.group(0))

    # taksit_sayisi
    taksit_match = re.search(r'(\d+)\s*taksit', text, re.IGNORECASE)
    if taksit_match:
        result["taksit_sayisi"].append(taksit_match.group(0))

    # masraf_bilgisi
    masraf_match = re.search(r'Tahsis\s*ücreti\s*müşteriden\s*peşin\s*olarak\s*tahsil\s*edilecektir', text, re.IGNORECASE)
    if masraf_match:
        result["masraf_bilgisi"].append(masraf_match.group(0))
    else:
        masraf_match = re.search(r'Finansman\s*tahsis\s*ücreti.*?%(\d+(?:,\d+)?)', text, re.IGNORECASE)
        if masraf_match:
            result["masraf_bilgisi"].append("Finansman tahsis ücreti: %" + masraf_match.group(1))

    # hedef_kitle
    hedef_match = re.search(r'hak\s*sahibi\s*olduğunuz\s*orman\s*statüsünü\s*yitirmiş\s*arazi', text, re.IGNORECASE)
    if hedef_match:
        result["hedef_kitle"].append("Hak sahibi olduğunuz orman statüsünü yitirmiş arazi sahipleri")
    else:
        hedef_match = re.search(r'hak\s*sahipliği\s*belgeniz\s*varsa', text, re.IGNORECASE)
        if hedef_match:
            result["hedef_kitle"].append("Hak sahipliği belgesi olan kişiler")

    # para_birimi
    para_match = re.findall(r'TL', text)
    if para_match:
        result["para_birimi"].append("TL")

    # kosullar
    kosullar_match = re.search(r'6292\s*sayılı\s*Kanun\s*kapsamında', text, re.IGNORECASE)
    if kosullar_match:
        result["kosullar"].append(kosullar_match.group(0))
    kosullar_match = re.search(r'400\s*metrekareye\s*kadar\s*araziler', text, re.IGNORECASE)
    if kosullar_match:
        result["kosullar"].append(kosullar_match.group(0))

    return result
